<template><section class="card" aria-labelledby="implementation-emails-title"><h2 id="implementation-emails-title">E-mails da implantação</h2><p>As notificações usam o serviço de e-mail do Help Desk. A aceitação do envio e a confirmação da entrega são etapas diferentes.</p><label for="implementation-email-document">Cadastro ou revisão</label><select id="implementation-email-document" class="input" v-model="selected" :disabled="busy" @change="refresh"><option value="">Selecione um registro</option><option v-for="doc in documents" :key="doc.id" :value="doc.id">{{doc.label}}</option></select><button type="button" class="btn" :disabled="busy" @click="loadDocuments">Atualizar situação</button><p v-if="error" role="alert">{{error}}</p><p v-else role="status">{{busy?'Consultando…':message}}</p><table v-if="notifications.length"><thead><tr><th>Destinatário</th><th>Situação</th></tr></thead><tbody><tr v-for="row in notifications" :key="row.id"><td>{{row.recipient_display}}</td><td>{{emailStatusLabel(row.state)}}</td></tr></tbody></table><p class="muted">O compartilhamento é restrito a pessoas da equipe com acesso à conta. Envios sem confirmação precisam de conferência antes de uma nova tentativa.</p></section></template>
<script setup lang="ts">
import {ref,onActivated,onDeactivated,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {runtime} from './runtime';import {emailStatusLabel} from './email-status';
const rt=runtime(),route=useRoute(),documents=ref<Array<{id:string;label:string}>>([]),selected=ref(''),notifications=ref<Array<{id:string;state:string;recipient_display:string}>>([]),busy=ref(false),error=ref(''),message=ref('Selecione um registro para consultar.'),alive=ref(true);let revision=0;
let listRevision=0;
const deactivate=()=>{alive.value=false;revision++;listRevision++;busy.value=false;};onBeforeUnmount(deactivate);onDeactivated(deactivate);
async function refresh(){const stamp=++revision;notifications.value=[];error.value='';if(!selected.value){message.value='Selecione um registro para consultar.';busy.value=false;return;}busy.value=true;try{const result=await rt.json('/notifications/'+encodeURIComponent(selected.value)+'?account_id='+encodeURIComponent(rt.accountId));if(!alive.value||!rt.live||stamp!==revision)return;notifications.value=result.data.notifications??[];message.value=notifications.value.length?'Atualize para consultar novas confirmações.':emailStatusLabel(result.data.email_status);}catch{if(alive.value&&rt.live&&stamp===revision)error.value='Não foi possível consultar os e-mails. Tente atualizar.';}finally{if(alive.value&&rt.live&&stamp===revision)busy.value=false;}}
onActivated(()=>{alive.value=true;void loadDocuments();});
async function loadDocuments(){if(!alive.value||!rt.live)return;const stamp=++listRevision;revision++;notifications.value=[];busy.value=true;error.value='';try{const [drafts,tickets]=await Promise.all([rt.json('/rpc',{method:'list_drafts_by_tokens',args:{},account_id:rt.accountId}),rt.json('/query',{table:'setup_tickets',action:'select',filters:[],account_id:rt.accountId})]);if(!alive.value||!rt.live||stamp!==listRevision)return;documents.value=[...drafts.data,...tickets.data].map((row:any)=>({id:row.id,label:(row.ticket_number?'Revisão '+row.ticket_number:'Rascunho')+' — '+(row.obra_nome||'Sem nome')}));const wanted=selected.value||route.query.document;selected.value=documents.value.some(doc=>doc.id===wanted)?String(wanted):documents.value[0]?.id??'';busy.value=false;await refresh();}catch{if(alive.value&&rt.live&&stamp===listRevision){busy.value=false;error.value='Não foi possível carregar os registros desta conta.';}}}
</script>
